package local.campus.review.workbench;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.ObjectNode;
import local.campus.review.auth.*;
import local.campus.review.common.*;
import local.campus.review.reference.LibraryGenerationService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.util.*;
@Service
public class ReleaseService {
    final DatasetService data;final TrainingService training;final LibraryGenerationService libraries;
    public ReleaseService(DatasetService data,TrainingService training,LibraryGenerationService libraries){this.data=data;this.training=training;this.libraries=libraries;}
    public record Create(String organizationId,String scene,String name,String modelId,String evaluationId,String preset){}
    public JsonNode create(CurrentUser actor,Create input){
        AccessPolicy.requireAdmin(actor);String org=input.organizationId();if(org!=null&&!org.equals("0"))data.organization(actor,org);else org=null;
        if(!Set.of("TEXT_REUSE","PAIR_PREDICTION").contains(Objects.toString(input.scene(),"")))throw new ApiException(400,"VALIDATION_ERROR","请选择发布场景");String name=DatasetService.name(input.name());
        if(input.scene().equals("TEXT_REUSE")){if(!Set.of("CURRENT","LEGACY").contains(Objects.toString(input.preset(),"")))throw new ApiException(400,"VALIDATION_ERROR","请选择兼容的审核配置");}
        else{var model=training.model(actor,input.modelId());if(Boolean.TRUE.equals(model.get("archived")))throw new ApiException(409,"MODEL_ARCHIVED","请先恢复模型");if(org!=null&&!org.equals(model.get("organization_id").toString()))throw new ApiException(400,"VALIDATION_ERROR","模型与目标部门不匹配");var evaluation=data.runRow(actor,input.evaluationId());if(!"EVALUATE".equals(evaluation.get("action"))||!"COMPLETED".equals(evaluation.get("status"))||!input.modelId().equals(JsonSupport.parse(data.json,evaluation.get("options_json").toString()).path("modelId").asText()))throw new ApiException(400,"VALIDATION_ERROR","请选择该模型已完成的独立评价");}
        String id=UUID.randomUUID().toString();data.db.update("INSERT INTO model_release(id,organization_id,scene,name,model_id,evaluation_run_id,preset,status,created_by,created_at) VALUES(?,?,?,?,?,?,?,'QUEUED',?,UTC_TIMESTAMP(3))",id,org,input.scene(),name,input.scene().equals("TEXT_REUSE")?null:input.modelId(),input.scene().equals("TEXT_REUSE")?null:input.evaluationId(),input.scene().equals("TEXT_REUSE")?input.preset():null,actor.userId());return data.json.createObjectNode().put("id",id);
    }
    public JsonNode list(CurrentUser actor,int page){data.role(actor);if(page<1)throw new ApiException(400,"VALIDATION_ERROR","分页无效");var result=data.json.createObjectNode().put("total",data.db.queryForObject("SELECT COUNT(*) FROM model_release",Long.class));var items=result.putArray("items");for(var row:data.db.queryForList("SELECT r.*,o.name AS department FROM model_release r LEFT JOIN organization o ON o.id=r.organization_id ORDER BY r.created_at DESC,r.id DESC LIMIT 20 OFFSET ?",(page-1L)*20)){var item=data.json.createObjectNode().put("id",row.get("id").toString()).put("name",row.get("name").toString()).put("scene",row.get("scene").toString()).put("organizationId",Objects.toString(row.get("organization_id"),"0")).put("department",Objects.toString(row.get("department"),"校级默认")).put("status",row.get("status").toString()).put("error",Objects.toString(row.get("error_message"),""));if(row.get("manifest_json")!=null)item.set("manifest",JsonSupport.parse(data.json,row.get("manifest_json").toString()));items.add(item);}result.set("pointers",data.json.valueToTree(data.db.queryForList("SELECT scope_key AS scopeKey,release_id AS releaseId FROM model_release_pointer")));result.set("history",data.json.valueToTree(data.db.queryForList("SELECT scope_key AS scopeKey,previous_id AS previousId,release_id AS releaseId,DATE_FORMAT(created_at,'%Y-%m-%dT%H:%i:%sZ') AS createdAt FROM model_release_event ORDER BY id DESC LIMIT 20")));return result;}
    public JsonNode evaluations(CurrentUser actor,String model){training.model(actor,model);return data.json.valueToTree(data.db.queryForList("SELECT id AS runId,JSON_UNQUOTE(JSON_EXTRACT(options_json,'$.name')) AS name FROM ml_run WHERE action='EVALUATE' AND status='COMPLETED' AND JSON_UNQUOTE(JSON_EXTRACT(options_json,'$.modelId'))=? ORDER BY created_at DESC LIMIT 100",model));}
    @Transactional public JsonNode activate(CurrentUser actor,String id,String expected){
        AccessPolicy.requireAdmin(actor);DatasetService.identity(id);var row=data.db.queryForMap("SELECT * FROM model_release WHERE id=?",id);if(!"READY".equals(row.get("status")))throw new ApiException(409,"RELEASE_NOT_READY","请等待版本核验完成");
        String org=Objects.toString(row.get("organization_id"),"0"),scene=row.get("scene").toString(),scope=org+":"+scene;if(!org.equals("0"))data.organization(actor,org);
        var manifest=JsonSupport.parse(data.json,row.get("manifest_json").toString());try{var files=manifest.path("verifiedFiles").fields();while(files.hasNext()){var entry=files.next();var file=data.settings.root().resolve(entry.getKey()).normalize();if(!file.startsWith(data.settings.root())||!sha(file).equals(entry.getValue().asText()))throw new IllegalStateException();}}catch(Exception e){throw new ApiException(409,"ARTIFACT_CHANGED","已核验工件发生变化，请重新登记版本");}if(scene.equals("TEXT_REUSE")&&!manifest.path("textConfig").path("featureSpaceId").equals(libraries.currentManifest().path("producerConfigs").path("textConfig").path("featureSpaceId")))throw new ApiException(409,"INDEX_INCOMPATIBLE","当前参考库特征空间不兼容，请先准备匹配索引");
        data.db.update("INSERT IGNORE INTO model_release_pointer(scope_key,release_id,updated_at) VALUES(?,NULL,UTC_TIMESTAMP(3))",scope);var pointer=data.db.queryForMap("SELECT release_id FROM model_release_pointer WHERE scope_key=? FOR UPDATE",scope);String old=Objects.toString(pointer.get("release_id"),"");if(!old.equals(Objects.toString(expected,"")))throw new ApiException(409,"RELEASE_CONFLICT","活动版本已变化，请刷新后重试");
        if(scene.equals("PAIR_PREDICTION")){var model=data.db.queryForMap("SELECT archived,run_id FROM ml_model WHERE id=? FOR UPDATE",row.get("model_id"));if(Boolean.TRUE.equals(model.get("archived")))throw new ApiException(409,"MODEL_ARCHIVED","发布模型已归档");try{String actual=sha(training.directory(model.get("run_id").toString()).resolve("output/manifest.json"));if(!actual.equals(manifest.path("modelManifestSha256").asText()))throw new IllegalStateException();}catch(Exception e){throw new ApiException(409,"MODEL_CHANGED","模型工件已变化，请重新登记核验");}}
        data.db.update("UPDATE model_release_pointer SET release_id=?,updated_at=UTC_TIMESTAMP(3) WHERE scope_key=?",id,scope);data.db.update("INSERT INTO model_release_event(scope_key,previous_id,release_id,actor_id,created_at) VALUES(?,?,?,?,UTC_TIMESTAMP(3))",scope,old.isEmpty()?null:old,id,actor.userId());return data.json.createObjectNode().put("activeId",id);
    }
    private static byte[] hashStream(java.io.InputStream stream)throws Exception{var hash=java.security.MessageDigest.getInstance("SHA-256");byte[] buffer=new byte[65536];int n;while((n=stream.read(buffer))!=-1)hash.update(buffer,0,n);return hash.digest();}
    static String sha(java.nio.file.Path file)throws Exception{try(var stream=java.nio.file.Files.newInputStream(file)){return HexFormat.of().formatHex(hashStream(stream));}}
    @Transactional public JsonNode reset(CurrentUser actor,String org,String scene,String expected){AccessPolicy.requireAdmin(actor);if(!Set.of("TEXT_REUSE","PAIR_PREDICTION").contains(scene))throw new ApiException(400,"VALIDATION_ERROR","场景无效");if(!org.equals("0"))data.organization(actor,org);String key=org+":"+scene;data.db.update("INSERT IGNORE INTO model_release_pointer(scope_key,updated_at) VALUES(?,UTC_TIMESTAMP(3))",key);var row=data.db.queryForMap("SELECT release_id FROM model_release_pointer WHERE scope_key=? FOR UPDATE",key);String old=Objects.toString(row.get("release_id"),"");if(!old.equals(Objects.toString(expected,"")))throw new ApiException(409,"RELEASE_CONFLICT","活动版本已变化，请刷新");data.db.update("UPDATE model_release_pointer SET release_id=NULL,updated_at=UTC_TIMESTAMP(3) WHERE scope_key=?",key);data.db.update("INSERT INTO model_release_event(scope_key,previous_id,release_id,actor_id,created_at) VALUES(?,?,NULL,?,UTC_TIMESTAMP(3))",key,old.isEmpty()?null:old,actor.userId());return data.json.createObjectNode().put("reset",true);}
    public ObjectNode textSelection(String org,JsonNode fallback){
        var rows=data.db.queryForList("SELECT r.id,r.manifest_json FROM model_release_pointer p JOIN model_release r ON r.id=p.release_id WHERE p.scope_key IN (?,?) ORDER BY (p.scope_key=?) DESC LIMIT 1",org+":TEXT_REUSE","0:TEXT_REUSE",org+":TEXT_REUSE");var result=data.json.createObjectNode();if(rows.isEmpty()){result.set("textConfig",fallback);return result;}result.put("releaseId",rows.getFirst().get("id").toString());result.set("textConfig",JsonSupport.parse(data.json,rows.getFirst().get("manifest_json").toString()).path("textConfig"));return result;
    }
    public JsonNode predict(CurrentUser actor,String org,JsonNode rows)throws Exception{
        data.organization(actor,org);if(rows==null||!rows.isArray()||rows.isEmpty()||rows.size()>100)throw new ApiException(400,"VALIDATION_ERROR","每次可提交1—100组句对");for(var row:rows)for(String key:List.of("sentence1","sentence2"))if(!row.path(key).isTextual()||row.path(key).asText().isBlank()||row.path(key).asText().length()>10000)throw new ApiException(400,"VALIDATION_ERROR","请填写有效文本，每段最多10000字符");
        var releases=data.db.queryForList("SELECT r.* FROM model_release_pointer p JOIN model_release r ON r.id=p.release_id WHERE p.scope_key IN (?,?) ORDER BY (p.scope_key=?) DESC LIMIT 1",org+":PAIR_PREDICTION","0:PAIR_PREDICTION",org+":PAIR_PREDICTION");if(releases.isEmpty())throw new ApiException(409,"NO_ACTIVE_MODEL","该部门尚无已发布的句对模型");var release=releases.getFirst();var model=training.model(actor,release.get("model_id").toString());if(Boolean.TRUE.equals(model.get("archived")))throw new ApiException(409,"MODEL_ARCHIVED","发布模型已归档，请选择可用版本");String id=UUID.randomUUID().toString();var manifest=JsonSupport.parse(data.json,release.get("manifest_json").toString());var config=data.json.createObjectNode().put("action","PREDICT").put("model",training.directory(model.get("run_id").toString()).resolve("output").toString()).put("modelManifestSha256",manifest.path("modelManifestSha256").asText());config.set("rows",rows);var result=(ObjectNode)ProjectPython.delivery(data.settings,data.json,data.settings.runtime().resolve("delivery/predictions").resolve(id),config);result.put("predictionId",id).put("releaseId",release.get("id").toString());data.db.update("INSERT INTO model_release_prediction(id,release_id,input_sha256,result_json,created_by,created_at) VALUES(?,?,?,?,?,UTC_TIMESTAMP(3))",id,release.get("id"),JsonSupport.hash(data.json,rows),result.toString(),actor.userId());return result;
    }
    public void verify(Map<String,Object> row)throws Exception{String id=row.get("id").toString();var config=data.json.createObjectNode();if(row.get("model_id")==null)config.put("action","CONFIG").put("preset",row.get("preset").toString());else{String run=data.db.queryForObject("SELECT run_id FROM ml_model WHERE id=?",String.class,row.get("model_id"));config.put("action","MODEL").put("model",training.directory(run).resolve("output").toString()).put("evaluation",training.directory(row.get("evaluation_run_id").toString()).resolve("output/manifest.json").toString());}var result=ProjectPython.delivery(data.settings,data.json,data.settings.runtime().resolve("delivery/releases").resolve(id),config);data.db.update("UPDATE model_release SET status='READY',manifest_json=?,error_message=NULL WHERE id=?",result.toString(),id);}
}
